package com.bank.spark.model;

// Rows landing in one partition after a shuffle, plus its dominant key.
public class PartitionLoad {
    private final int partitionId;
    private final String dominantKey;
    private final long rowCount;

    public PartitionLoad(int partitionId, String dominantKey, long rowCount) {
        this.partitionId = partitionId;
        this.dominantKey = dominantKey;
        this.rowCount = rowCount;
    }

    public int getPartitionId() { return partitionId; }
    public String getDominantKey() { return dominantKey; }
    public long getRowCount() { return rowCount; }
}
