package com.bank.spark.service;

import com.bank.spark.model.PartitionLoad;

import java.util.List;

// Detects skew from per-partition row counts (mirrors the Spark UI task summary).
public class SkewDetector {

    private final double skewRatioThreshold;

    public SkewDetector(double skewRatioThreshold) {
        this.skewRatioThreshold = skewRatioThreshold;
    }

    public long median(List<PartitionLoad> loads) {
        long[] counts = loads.stream().mapToLong(PartitionLoad::getRowCount).sorted().toArray();
        return counts[counts.length / 2];
    }

    public PartitionLoad heaviest(List<PartitionLoad> loads) {
        return loads.stream().max((a, b) -> Long.compare(a.getRowCount(), b.getRowCount())).orElseThrow();
    }

    // Skew if max/median exceeds the threshold.
    public boolean isSkewed(List<PartitionLoad> loads) {
        long med = Math.max(1, median(loads));
        return (double) heaviest(loads).getRowCount() / med >= skewRatioThreshold;
    }

    public double maxToMedianRatio(List<PartitionLoad> loads) {
        long med = Math.max(1, median(loads));
        return (double) heaviest(loads).getRowCount() / med;
    }
}
