package com.bank.spark;

import com.bank.spark.model.PartitionLoad;
import com.bank.spark.service.SkewDetector;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SkewDetectDemo {

    private static final Logger log = Logger.getLogger(SkewDetectDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SkewDetector detector = new SkewDetector(10.0); // 10x = skew

        // After shuffling transactions by accountId: one hot corporate account dominates.
        List<PartitionLoad> loads = List.of(
                new PartitionLoad(0, "CUR3002", 12_000),
                new PartitionLoad(1, "SAV2003", 9_500),
                new PartitionLoad(2, "SAV2001", 2_400_000),  // hot key: pooling account
                new PartitionLoad(3, "CUR3001", 11_000),
                new PartitionLoad(4, "SAV2002", 10_200)
        );

        long med = detector.median(loads);
        PartitionLoad hot = detector.heaviest(loads);
        double ratio = detector.maxToMedianRatio(loads);

        log.info(() -> "Median partition size: " + med + " rows");
        log.info(() -> "Heaviest partition: #" + hot.getPartitionId() + " key=" + hot.getDominantKey()
                + " rows=" + hot.getRowCount());
        log.info(() -> "Max/median ratio: " + String.format("%.1f", ratio) + "x");

        if (detector.isSkewed(loads)) {
            log.severe("DATA SKEW DETECTED: task for partition " + hot.getPartitionId()
                    + " (hot key " + hot.getDominantKey() + ") will straggle ~" + String.format("%.0f", ratio) + "x longer");
            log.warning("Spark UI would show this one task 10-100x slower with huge shuffle read.");
        } else {
            log.info("No significant skew.");
        }
    }
}

